      "causa_raiz": "Quantidade crítica de Draw Calls (atingindo até 13.967, ultrapassando o orçamento de 2.579), provocando sobrecarga massiva na submissão de renderização pela CPU e estourando o tempo de GPU em 41.78ms.",
      "codigo_refatorado": "using UnityEngine;

public class RuntimeMeshBatcher : MonoBehaviour
{
    [SerializeField] private bool disableSourceObjects = true;

    private void Start()
    {
        BatchStaticMeshes();
    }

    public void BatchStaticMeshes()
    {
        MeshFilter[] filters = GetComponentsInChildren<MeshFilter>();
        CombineInstance[] combine = new CombineInstance[filters.Length];

        for (int i = 0; i < filters.Length; i++)
        {
            combine[i].mesh = filters[i].sharedMesh;
            combine[i].transform = filters[i].transform.localToWorldMatrix;
            if (disableSourceObjects && filters[i].gameObject != gameObject)
            {
                filters[i].gameObject.SetActive(false);
            }
        }

        MeshFilter myFilter = gameObject.AddComponent<MeshFilter>();
        MeshRenderer myRenderer = gameObject.AddComponent<MeshRenderer>();

        myFilter.mesh = new Mesh();
        myFilter.mesh.CombineMeshes(combine, true, true);
        if (filters.Length > 0 && filters[0].GetComponent<MeshRenderer>() != null)
        {
            myRenderer.sharedMaterial = filters[0].GetComponent<MeshRenderer>().sharedMaterial;
        }
    }
}",
      "explicacao_didatica": "Um Draw Call é um pedido que a CPU faz para a GPU pedindo para desenhar um objeto na tela. Quando você tem quase 14.000 objetos individuais sendo desenhados separadamente, a CPU fica sobrecarregada enviando esses comandos e a GPU perde desempenho trocando de contexto. Ao combinar várias malhas pequenas em uma única malha maior que compartilha o mesmo material, reduzimos drasticamente o número de chamadas de desenho para apenas uma, mantendo o jogo fluido a 60 FPS."
    }
  ],
  "dicas_level_design": "1. Marque objetos estáticos do cenário como 'Static' no Inspector para permitir o Batching Estático nativo da Unity.
2. Utilize Texture Atlasing para consolidar múltiplos materiais em um único material unificado, permitindo que objetos diferentes sejam combinados no mesmo Draw Call.
3. Configure o Occlusion Culling (Window > Rendering > Occlusion Culling) para garantir que objetos escondidos atrás de estruturas grandes não sejam processados pela GPU.
4. Implemente LOD (Level of Detail) e ative GPU Instancing nos materiais de objetos repetitivos como árvores, pedras e vegetação."
}

